const tabId = 725789690;

const videoUrls = [
  "https://www.youtube.com/watch?v=2uixLIvv4H0", // Most Homeowners Insulate Shed Roofs WRONG (Do This Instead)
  "https://www.youtube.com/watch?v=-yjJ7XRZiKY", // Simple and Easy DIY Shed Insulation - NO Soffit
  "https://www.youtube.com/watch?v=z3q2d5SXZ7w", // Insulation for Walls and Ceiling 10x12 Building
  "https://www.youtube.com/watch?v=rXeRLx9p5Oo", // Unbelievable Shed Ceiling Insulation Upgrade!
  "https://www.youtube.com/watch?v=kbWE0lz4QE0"  // #1 Insulation Mistake DIYers Always Regret
];

