// Find link to RXCB351525 product page
const prodLink = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a'));
  const target = links.find(a => a.href && a.href.includes('RXCB351525') || (a.textContent.includes('ROCKWOOL') && a.textContent.includes('R-15')));
  return target ? target.href : null;
});

console.log("Target product URL:", prodLink);
