  await tool.navigate({ tabId, url: prodLink });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });
}

const prodDetails = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.textContent?.trim() || document.title;
  // Look for price
  const priceContainer = document.querySelector('[data-testid="price-format"], .price-format__largePrice, .price, .price__format');
  const priceText = priceContainer ? priceContainer.innerText : document.querySelector('[class*="price"]')?.innerText;

  // Look for specifications or description
  const specs = Array.from(document.querySelectorAll('[data-testid="product-specifications"] tr, .specs-table tr, .bullet-list li')).map(li => li.innerText.trim()).filter(Boolean);

  return {
    title,
    priceText: priceText?.replace(/\s+/g, ' '),
    specsSnippet: specs.slice(0, 10),
    url: window.location.href
  };
});

