// Dimensions of 10x12 shed
const floorSqft = 120;
const wallSqft = 320;
const roofSqft = 150;
const totalSqft = floorSqft + wallSqft + roofSqft; // 590 sq ft

console.log(`10x12 Shed Envelope: Floor=${floorSqft} sqft, Walls=${wallSqft} sqft, Roof=${roofSqft} sqft. Total=${totalSqft} sqft.`);

// Strategy 1: Budget Fiberglass Batts
// Walls: Owens Corning R-13 Faced Roll (40 sq ft/roll @ $27.97) -> 320 / 40 = 8 rolls
// Ceiling: Owens Corning R-19 Faced (approx 40 sq ft/roll @ ~$35.00 or batts; if not shown exact retail, calculate per sq ft from R-13 ~ $0.85/sqft) + 12 Accuvent baffles ($5.98 ea = $71.76)
// Floor: Owens Corning R-13 Faced (120 / 40 = 3 rolls @ $27.97) + 6 mil poly 10x25 ($22.00) + insulation wire supports ($18.00)
// Misc: Tyvek tape / staples ($25.00)

// Strategy 2: Rockwool Mineral Wool + Continuous Rigid Foam Hybrid
// Walls: Rockwool R-15 Comfortbatt (59.7 sq ft/bag @ $84.98) -> 320 / 59.7 = 5.36 -> 6 bags = $509.88
// Ceiling: Rockwool R-15 Comfortbatt (150 / 59.7 = 2.51 -> 3 bags @ $84.98 = $254.94) + 2" Foamular NGX XPS R-10 4x8 sheets (32 sq ft/sheet @ $59.97 -> 150 / 32 = 4.68 -> 5 sheets = $299.85)
// Floor: 2" Foamular NGX XPS R-10 4x8 sheets (120 / 32 = 3.75 -> 4 sheets @ $59.97 = $239.88) + 6 mil poly ($22.00)
// Accessories: 2 cans Great Stuff ($16), 1 roll Tyvek/Sika tape ($14.97), 1 box Go Board washers & screws ($24.00) = ~$55.00

// Strategy 3: Closed-Cell Spray Foam Kit (Froth-Pak)
// Need 2" ccSPF everywhere (or 2" walls/floor, 3" roof):
// 1" board feet needed = (320 * 2") + (120 * 2") + (150 * 3") = 640 + 240 + 450 = 1,330 board feet.
// Froth-Pak 200 kit ($429.00) yields 200 board feet.
// Kits needed: 1330 / 200 = 6.65 -> 7 kits of Froth-Pak 200!
// 7 * $429.00 = $3,003.00!
// Or if 2" everywhere: 590 * 2 = 1,180 board feet -> 6 kits of Froth-Pak 200 = 6 * $429 = $2,574.00!
// Plus PPE (respirator, Tyvek suits, goggles, gloves) = $120.00. Total = ~$2,700 - $3,100!

console.log("Preliminary basket calculations complete.");

